// src/app/components/empleado-form/empleado-form.component.ts
import { Component } from '@angular/core';
import { Router } from '@angular/router';
import { Empleado } from '../../models/empleado.model';
import { EmpleadoService } from '../../services/empleado.service';

@Component({
  selector: 'app-empleado-form',
  templateUrl: './empleado-form.component.html',
  styleUrls: ['./empleado-form.component.css']
})
export class EmpleadoFormComponent {
  // Objeto ViewModel que se sincroniza bidireccionalmente con la Vista
  nuevoEmpleado: Empleado = {
    nombre: '',
    cargo: '',
    departamento: 'Tecnología',
    salario: 0
  };

  constructor(
    private empleadoService: EmpleadoService,
    private router: Router
  ) {}

  // Acción enviada al Modelo
  guardar(): void {
    if (this.nuevoEmpleado.nombre.trim()) {
      this.empleadoService.agregarEmpleado(this.nuevoEmpleado).subscribe(() => {
        this.router.navigate(['/empleados']);
      });
    }
  }
}

<!-- src/app/components/empleado-form/empleado-form.component.html -->
<div class="form-container">
  <h2>Registrar Nuevo Empleado</h2>
  <form (ngSubmit)="guardar()">
    <div class="grupo-campo">
      <label>Nombre Completo:</label>
      <input type="text" [(ngModel)]="nuevoEmpleado.nombre" name="nombre" required>
    </div>
    <div class="grupo-campo">
      <label>Cargo:</label>
      <input type="text" [(ngModel)]="nuevoEmpleado.cargo" name="cargo" required>
    </div>
    <div class="grupo-campo">
      <label>Departamento:</label>
      <select [(ngModel)]="nuevoEmpleado.departamento" name="departamento">
        <option value="Tecnología">Tecnología</option>
        <option value="Sistemas">Sistemas</option>
        <option value="Diseño">Diseño</option>
        <option value="Ventas">Ventas</option>
      </select>
    </div>
    <div class="grupo-campo">
      <label>Salario Mensual ($):</label>
      <input type="number" [(ngModel)]="nuevoEmpleado.salario" name="salario" required>
    </div>
    <button type="submit" class="btn-guardar">Registrar en el Modelo</button>
  </form>
</div>
